export interface PlacementPoint { x: number; y: number }
export interface PlacementBoard extends PlacementPoint { width: number; height: number }
export interface PlacementIntent {
  finger: PlacementPoint;
  held: PlacementPoint;
  target: PlacementPoint;
  board: PlacementBoard;
  snapRadius: number;
  opaqueFingerHit: boolean;
}

/** Display-space tolerance for the single already-selected sticker, not picking. */
export function placementSnapRadius(width: number, height: number, unit = 1): number {
